SELECT 
FROM insurance_policy i JOIN parcel p ON p.id = i.parcel_id
WHERE i.id = #{id}

SELECT 
FROM insurance_policy i JOIN parcel p ON p.id = i.parcel_id
WHERE i.parcel_id = #{parcelId}

SELECT 
FROM insurance_policy i JOIN parcel p ON p.id = i.parcel_id
WHERE i.user_id = #{userId}
AND i.status = #{status}
ORDER BY i.created_at DESC
LIMIT #{limit} OFFSET #{offset}

SELECT count(*) FROM insurance_policy i
WHERE i.user_id = #{userId}
AND i.status = #{status}
